L1: import { readFileSync } from "node:fs";
L2: import { spawnSync } from "node:child_process";
L3: import { resolve } from "node:path";
L4: import { fileURLToPath } from "node:url";
L5: 
L6: const UNPATCHED_DEV_ADVISORY = "https://github.com/advisories/GHSA-fc5q-39xc-vjpf";
L7: 
L8: /** Preserve the high/critical gate, with one dev-only advisory exception.
L9:  * Missing lock records, dependency cycles and unknown advisory chains fail closed. */
L10: export function auditFindings(report, lock) {
L11:   if (!report || report.error || !report.vulnerabilities) throw new Error("npm audit did not return a valid vulnerability report");
L12:   const vulnerabilities = report.vulnerabilities;
L13:   function isKnownDevChain(name, trail = new Set()) {
L14:     const item = vulnerabilities[name];
L15:     if (!item || trail.has(name) || !item.nodes?.length || !item.via?.length) return false;
L16:     if (!item.nodes.every((path) => lock.packages?.[path]?.dev === true)) return false;
L17:     const next = new Set([...trail, name]);
L18:     return item.via.every((via) => typeof via === "string"
L19:       ? isKnownDevChain(via, next)
L20:       : via.name === "picomatch" && via.url === UNPATCHED_DEV_ADVISORY && via.severity === "high");
L21:   }
L22:   const blocked = [], allowed = [];
L23:   for (const [name, item] of Object.entries(vulnerabilities)) {
L24:     if (!["high", "critical"].includes(item.severity)) continue;
L25:     if (item.severity === "high" && isKnownDevChain(name)) allowed.push(name);
L26:     else blocked.push(name);
L27:   }
L28:   return { blocked, allowed };
L29: }
L30: 
L31: function main() {
L32:   const executable = process.env.npm_execpath;
L33:   const result = executable
L34:     ? spawnSync(process.execPath, [executable, "audit", "--json"], { encoding: "utf8", maxBuffer: 10 * 1024 * 1024 })
L35:     : spawnSync("npm", ["audit", "--json"], { encoding: "utf8", maxBuffer: 10 * 1024 * 1024 });
L36:   if (result.error || result.signal || ![0, 1].includes(result.status)) throw new Error(result.error?.message || result.stderr || "npm audit failed");
L37:   const report = JSON.parse(result.stdout);
L38:   const { blocked, allowed } = auditFindings(report, JSON.parse(readFileSync("package-lock.json", "utf8")));
L39:   if (allowed.length) console.warn(`Temporary dev-only exception GHSA-fc5q-39xc-vjpf: ${allowed.join(", ")}. See docs/DEPENDENCY_AUDIT.md.`);
L40:   if (blocked.length) {
L41:     console.error(`Dependency audit blocked: ${blocked.join(", ")}`);
L42:     console.error(result.stdout);
L43:     process.exitCode = 1;
L44:   } else console.log("Dependency audit passed the high/critical gate; moderate findings retain the existing policy.");
L45: }
L46: if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
L47:   try { main(); } catch (error) { console.error(error.message); process.exitCode = 1; }
L48: }
